Print Sum of all Substrings of a String Representing a NumberGiven an integer represented as a string, we need to get the sum of all possible substrings of this string.
            C++

    #include <bits/stdc++.h>
using namespace std;

int main() {
    string s = "1234";
    int res = 0;
    int n = s.length();
    for (int i = 0; i < n; i++) {
        for (int len = 1; len <= n - i; len++) {
            string sub = (s.substr(i, len));

            // Convert the substring into 
            // integer number
            int x = stoi(sub);
            res += x;
        }
    }
    cout << res;
    return 0;
}

